void mainImage(out vec4 couleurFragment, in vec2 coordFragment) {
    vec2 resolution = iResolution.xy;
    float temps = iTime;
    vec2 positionEcran = (coordFragment * 2.0 - resolution) / resolution.y;

    float distanceCamera = 2.2;
    float angleCamera = temps * 0.3;
    vec3 origineRayon = vec3(sin(angleCamera) * distanceCamera, 0.0, cos(angleCamera) * distanceCamera);
    vec3 pointCible = vec3(0.0, 0.0, 0.0);
    vec3 axeZ = normalize(pointCible - origineRayon);
    vec3 axeX = normalize(cross(axeZ, vec3(0, 1, 0)));
    vec3 axeY = normalize(cross(axeX, axeZ));
    vec3 directionRayon = normalize(positionEcran.x * axeX + positionEcran.y * axeY + 1.2 * axeZ);

    vec3 couleurTotale = vec3(0);
    float distanceRayon = 0.01;

    for (float i = 0.; i < 140.; i++) {
        vec3 positionEspace = origineRayon + distanceRayon * directionRayon;

        positionEspace.xz = mod(positionEspace.xz + 2., 4.) - 2.;

        float echelleFractale = 1.0;
        float accumulationOrbite = 0.0;

        for (int j = 0; j < 6; j++) {
            positionEspace = abs(positionEspace) - vec3(0.08, 0.4, 0.08);

            float rayonCarre = dot(positionEspace, positionEspace);
            float facteurInversion = max(0.18 / clamp(rayonCarre, 0.001, 10.0), 0.45);
            positionEspace *= facteurInversion;
            echelleFractale *= facteurInversion;

            float cosinusRotation1 = cos(0.357), sinusRotation1 = sin(0.357);
            positionEspace.xy = vec2(positionEspace.x * cosinusRotation1 - positionEspace.y * sinusRotation1, positionEspace.x * sinusRotation1 + positionEspace.y * cosinusRotation1);

            float cosinusRotation2 = cos(0.268), sinusRotation2 = sin(0.268);
            positionEspace.yz = vec2(positionEspace.y * cosinusRotation2 - positionEspace.z * sinusRotation2, positionEspace.y * sinusRotation2 + positionEspace.z * cosinusRotation2);

            accumulationOrbite += length(positionEspace.xy);
        }

        float distanceSignee = (length(positionEspace.xy) - 0.05) / echelleFractale;
        distanceSignee = max(abs(distanceSignee), 0.0008);

        float scintillement = 0.9 + 0.1 * sin(temps * 12.0 + distanceRayon * 5.0);
        vec3 paletteCouleur = 0.5 + 0.5 * cos(accumulationOrbite * 1.25 + vec3(0.0, 1.256, 2.513));

        couleurTotale += (paletteCouleur * scintillement) / (distanceSignee * 380.0);
        distanceRayon += distanceSignee * 0.08;
    }

    couleurFragment = vec4(tanh(couleurTotale / 6.0), 1.0);
    couleurFragment.rgb = pow(couleurFragment.rgb, vec3(1.6));
}
